ALTER TABLE public.marketing_inquiries ADD COLUMN social text NOT NULL DEFAULT '';
ALTER POLICY "Visitors can submit inquiries only" ON public.marketing_inquiries WITH CHECK (
((kind = ANY (ARRAY['review'::text, 'consultation'::text])) AND ((char_length(btrim(business)) >= 2) AND (char_length(btrim(business)) <= 120)) AND (char_length(business) <= 120) AND ((char_length(btrim(contact_name)) >= 2) AND (char_length(btrim(contact_name)) <= 100)) AND (char_length(contact_name) <= 100) AND ((char_length(email) >= 3) AND (char_length(email) <= 200)) AND (email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text) AND (char_length(phone) <= 30) AND (phone ~ '^[0-9+().[:space:]-]*$'::text) AND (char_length(website) <= 200) AND ((website = ''::text) OR (website ~ '^https?://[^[:space:]/?#]+[^[:space:]]*$'::text)) AND (char_length(social) <= 200) AND ((social = ''::text) OR (social ~ '^https?://[^[:space:]/?#]+[^[:space:]]*$'::text)) AND (char_length(industry) <= 100) AND (char_length(services) <= 500) AND (char_length(message) <= 1500) AND (((kind = 'review'::text) AND ((char_length(btrim(industry)) >= 2) AND (char_length(btrim(industry)) <= 100)) AND ((char_length(btrim(message)) >= 5) AND (char_length(btrim(message)) <= 1500)) AND (services = ''::text)) OR ((kind = 'consultation'::text) AND ((char_length(btrim(services)) >= 2) AND (char_length(btrim(services)) <= 500)) AND (website = ''::text) AND (social = ''::text) AND (industry = ''::text))))
);